<?php require '_h.php';$m=$_GET['m']??'berita';if(!isset($M[$m]))die;[$title,$F]=$M[$m];$id=(int)($_GET['id']??0);$err='';
if($_SERVER['REQUEST_METHOD']=='POST'){chk();try{
 if(isset($_POST['del']))q("DELETE FROM $m WHERE id=?",[$_POST['del']]);
 else{$d=[];foreach($F as $k=>$t){if($t=='file'&&$k=='gambar'&&($_POST['gambar_mode']??'')=='link'){$u=urlFoto($_POST['gambar_url']??'');if(!$u)throw new Exception('Link foto tidak valid. Harus diawali http:// atau https://');$d[$k]=$u;continue;}
 if($t=='file'){$n=upload($_FILES[$k]??[],10e6);if($n)$d[$k]=$n;elseif(!empty($_FILES[$k]['name']))throw new Exception('Berkas "'.$_FILES[$k]['name'].'" gagal diunggah. Gunakan JPG/PNG/WEBP (PDF untuk dokumen), maksimal 10MB.');}else $d[$k]=($t=='number'&&($_POST[$k]??'')==='')?0:($_POST[$k]??'');}
  if($m=='peta'&&str_contains($d['lat']??'',',')){[$d['lat'],$d['lng']]=array_map('trim',explode(',',$d['lat'],2));}
  if($id)q("UPDATE $m SET ".implode(',',array_map(fn($k)=>"$k=?",array_keys($d)))." WHERE id=?",[...array_values($d),$id]);
  else q("INSERT INTO $m(".implode(',',array_keys($d)).") VALUES(".implode(',',array_fill(0,count($d),'?')).")",array_values($d));}
 header("Location: crud.php?m=$m");exit;}catch(Exception $x){$err=preg_match('/^(Berkas|Link)/',$x->getMessage())?$x->getMessage():'Gagal menyimpan (data ganda/tidak valid).';}}
$row=$id?q("SELECT * FROM $m WHERE id=?",[$id])->fetch():[];$cols=array_slice(array_keys($F),0,4);?>
<h4><?=$title?></h4><?php if($m=='peta'):?><div class="alert alert-info small">Cara dapat koordinat: buka Google Maps → klik kanan pada lokasi → klik angka koordinat (otomatis tersalin) → tempel ke kolom <b>Lat</b> (boleh langsung format <code>-8.7480, 115.8000</code>, kolom Lng terisi otomatis). Pilih <b>Kategori</b> (Warung Makan, Penginapan, dll.) agar ikonnya muncul di peta.</div><?php endif?><?php if($err):?><div class="alert alert-danger"><?=$err?></div><?php endif?>
<form method="post" enctype="multipart/form-data" class="card card-body mb-4"><input type="hidden" name="t" value="<?=csrf()?>"><div class="row g-2">
<?php foreach($F as $k=>$t):?><div class="col-md-6"><label class="form-label small mb-0"><?=['link_tiket'=>'Link tombol Kunjungi Destinasi (web / Google Maps)','jarak'=>'Keterangan jarak (contoh: ± 15 menit dari dermaga)','aktivitas'=>'Daftar aktivitas (satu baris = satu poin)'][$k]??ucfirst(str_replace('_',' ',$k))?></label>
<?php if($t=='textarea'):?><textarea name="<?=$k?>" class="form-control" rows="3"><?=e($row[$k]??'')?></textarea>
<?php elseif($t=='file'&&$k=='gambar'):?><?php $cur=(string)($row[$k]??'');$isU=isUrlImg($cur);?>
<div class="btn-group btn-group-sm w-100 mb-2" role="group"><input type="radio" class="btn-check" name="gambar_mode" id="gm_up" value="upload" <?=$isU?'':'checked'?>><label class="btn btn-outline-success" for="gm_up"><i class="bi bi-upload"></i> Upload file</label><input type="radio" class="btn-check" name="gambar_mode" id="gm_ln" value="link" <?=$isU?'checked':''?>><label class="btn btn-outline-success" for="gm_ln"><i class="bi bi-link-45deg"></i> Pakai link foto</label></div>
<div id="gm_upbox" <?=$isU?'style="display:none"':''?>><input type="file" name="<?=$k?>" class="form-control"><?php if($cur&&!$isU):?><div class="form-text">Sudah ada: <?=e($cur)?> (pilih berkas baru untuk mengganti)</div><?php endif?></div>
<div id="gm_lnbox" <?=$isU?'':'style="display:none"'?>><input type="url" name="gambar_url" id="gm_url" value="<?=e($isU?$cur:'')?>" class="form-control" placeholder="https://... (alamat gambar)"><div class="form-text">Di Google: klik kanan foto → <b>Salin alamat gambar</b> → tempel di sini. Link share Google Drive (publik) juga bisa.</div><img id="gm_prev" alt="" referrerpolicy="no-referrer" style="display:none;max-height:120px;border-radius:10px;margin-top:6px"></div>
<script>(function(){var u=document.getElementById('gm_up'),l=document.getElementById('gm_ln'),ub=document.getElementById('gm_upbox'),lb=document.getElementById('gm_lnbox'),i=document.getElementById('gm_url'),p=document.getElementById('gm_prev');
function t(){var k=l.checked;ub.style.display=k?'none':'';lb.style.display=k?'':'none';}function pv(){var v=i.value.trim();if(/^https?:\/\//i.test(v)){p.src=v;p.style.display='';}else p.style.display='none';}
u.onchange=l.onchange=t;i.oninput=pv;p.onerror=function(){p.style.display='none'};pv();})();</script>
<?php elseif($t=='file'):?><input type="file" name="<?=$k?>" class="form-control"><?php if(!empty($row[$k])):?><div class="form-text">Sudah ada: <?=e($row[$k])?> (pilih berkas baru untuk mengganti)</div><?php endif?><?php elseif(str_contains($t,',')):?><select name="<?=$k?>" class="form-select"><?php foreach(explode(',',$t) as $o):?><option <?=($row[$k]??'')==$o?'selected':''?>><?=$o?></option><?php endforeach?></select>
<?php else:?><input type="<?=$t?>" name="<?=$k?>" value="<?=e($row[$k]??'')?>" class="form-control"><?php endif?></div><?php endforeach?></div>
